export const modules = [
  {id:'basics', name:'Fundamentals', icon:'◇', level:'Beginner', subtitle:'Data, code & trust boundaries', color:'mint'},
  {id:'reflected', name:'Reflected XSS', icon:'↗', level:'Beginner', subtitle:'Follow a request into a response', color:'blue'},
  {id:'stored', name:'Stored XSS', icon:'▤', level:'Intermediate', subtitle:'Persistence & second visits', color:'violet'},
  {id:'dom', name:'DOM-based XSS', icon:'⌘', level:'Intermediate', subtitle:'Sources, transforms & sinks', color:'blue'},
  {id:'encoding', name:'Output encoding', icon:'&', level:'Intermediate', subtitle:'Match the parser context', color:'mint'},
  {id:'filters', name:'Filters & sanitizers', icon:'⏣', level:'Advanced', subtitle:'Understand the limits of filters', color:'amber'},
  {id:'csp', name:'Content Security Policy', icon:'⊞', level:'Advanced', subtitle:'Predict what a policy permits', color:'violet'},
  {id:'debug', name:'Debugging & evidence', icon:'⌕', level:'Advanced', subtitle:'Prove the boundary, fix the cause', color:'amber'},
];
const M = '<mark data-proof="MRTD">MRTD</mark>';
export const exercises = [
  {id:'first-reflection',module:'basics',title:'Follow your first reflection',minutes:5,kind:'reflection',label:'Search query',placeholder:'Type a unique proof marker…',initial:'',goal:'Send the harmless marker MRTD_01 through a simulated search. Find it in the response and decide what this evidence proves.',lesson:'A reflection is input appearing in output. XSS requires a path that treats untrusted data as executable content. Start with a unique text marker so you can follow the data without assuming a vulnerability.',code:'// Simulated server response\nconst query = request.query.q;\nreturn `<p>Results for: ${escapeHTML(query)}</p>`;',context:'HTML text · encoded',source:'query.q',sink:'HTML text',transform:'HTML encoding',hints:['Use exactly MRTD_01 as your search term.','Compare the input and response. The marker is present, but the output boundary stays intact.'],explanation:'You traced MRTD_01 into an encoded HTML text node. This proves reflection only. It does not prove XSS or JavaScript execution. Always identify the parser context and a reachable execution path before making that claim.',fix:'Keep untrusted text in textContent or an auto-escaped text template.',answer:'MRTD_01'},
  {id:'classify-flow',module:'basics',title:'Name the data flow',minutes:5,kind:'choice',goal:'A comment is saved on Monday and appears in another reader’s page on Tuesday. Which delivery pattern is this?',lesson:'Reflected and stored describe delivery. DOM-based describes a client-side processing path. These dimensions can overlap: stored content can later reach a DOM sink.',code:'POST /comments → save(comment)\nGET /article  → loadComments()\nrender(comment.body)',context:'Delivery pattern',source:'comment body',sink:'later page render',transform:'storage',choices:[['reflected','Reflected delivery'],['stored','Stored delivery'],['fragment','Fragment-only delivery']],answer:'stored',hints:['Ask whether the input survives its original request.','The second reader receives data that was saved earlier.'],explanation:'This is stored delivery. Persistence separates submission from the later rendering step. You still need to inspect the renderer to know whether the saved text is safely encoded or can become active content.',fix:'Protect every output location, including previews, moderation pages and notifications.'},
  {id:'html-boundary',module:'reflected',title:'Cross the HTML text boundary',minutes:7,kind:'html',label:'Search query',placeholder:'Enter a harmless HTML proof marker…',goal:'In this model, the search template inserts input as HTML. Make the preview show the highlighted MRTD marker using a mark element with data-proof="MRTD".',lesson:'HTML injection changes the structure of a document. A harmless mark element is enough to demonstrate a broken HTML boundary. That structural change alone is not proof of JavaScript execution.',code:'// Intentionally unsafe model\nreturn `<p>Results for: ${query}</p>`;\n// Untrusted data is treated as markup.',context:'HTML text · raw',source:'query.q',sink:'raw HTML template',transform:'none',hints:['Use a mark element, not a script or an event handler.','Use <mark data-proof="MRTD">MRTD</mark>.'],explanation:'The modeled template interprets your marker as HTML structure. This demonstrates HTML injection. The lab deliberately does not run scripts, and the marker does not establish executable XSS. The root cause is a missing text-context encoding step.',fix:'Render query with textContent, or use automatic HTML output encoding.',answer:M},
  {id:'attribute-boundary',module:'reflected',title:'Recognize a quoted attribute',minutes:7,kind:'attribute',label:'Display name',placeholder:'End the quoted value and add the proof attribute…',goal:'The model inserts input inside a double-quoted value attribute. Add the harmless attribute data-proof="MRTD" by closing the existing value. Do not add an event handler.',lesson:'A quote can change an attribute value into a new attribute if the quote is not encoded. Angle brackets are not required for this boundary change.',code:'// Unsafe quoted attribute model\nreturn `<input value="${displayName}">`;',context:'Double-quoted HTML attribute',source:'displayName',sink:'input.value markup',transform:'none',hints:['The value begins inside a double quote. Close it first.','Try " data-proof="MRTD (the template supplies the last quote).'],explanation:'The model now contains a separate data-proof attribute. This is attribute injection, not execution. Encode quotes for the attribute context, keep attributes quoted, and avoid placing untrusted data in event-handler attributes.',fix:'Use input.value = displayName; avoid constructing input markup from strings.',answer:'" data-proof="MRTD'},
  {id:'script-context',module:'reflected',title:'Spot the JavaScript context',minutes:8,kind:'choice',goal:'A server interpolates a profile name into an inline JavaScript string. Choose the strongest redesign for plain text display.',lesson:'An HTML encoder does not make arbitrary JavaScript interpolation safe. The HTML parser and JavaScript parser have different delimiters. Prefer moving display data out of code entirely.',code:'<script>\n  const name = "${profileName}";\n  greeting.textContent = name;\n</script>',context:'Inline JavaScript string',source:'profileName',sink:'script text',transform:'interpolation',choices:[['html','Apply only HTML entity encoding'],['move','Pass structured data separately and render it with textContent'],['strip','Remove the word script']],answer:'move',hints:['The risk occurs before textContent is reached.','Remove the interpolation into executable source code.'],explanation:'The interpolation creates a JavaScript parsing boundary before the safe text sink. Use a safe data channel such as a JSON response with the correct content type, then render text through textContent. If embedding data in HTML, use a trusted framework serializer that also handles HTML parser boundaries.',fix:'Fetch structured data; assign greeting.textContent = data.profileName.'},
  {id:'stored-marker',module:'stored',title:'Leave a marker for the next visit',minutes:9,kind:'stored',label:'Comment body',placeholder:'Write a harmless HTML proof marker…',goal:'Save a mark element containing MRTD, then visit as the simulated reader. Completion requires the saved marker to appear during the second visit.',lesson:'Stored testing needs two distinct steps: write the input, then observe a later read. Here, comments are synthetic and stored only in your browser. No other person receives them.',code:'// Writer\ncomments.save(body);\n// Reader, later (unsafe model)\narticle.innerHTML = comments.latest();',context:'Persisted HTML · simulated reader',source:'saved comment',sink:'reader HTML',transform:'browser-local storage',hints:['Save <mark data-proof="MRTD">MRTD</mark>.','Saving is only the write step. Click Visit as reader to test the read step.'],explanation:'The saved value reached the modeled reader through a separate read operation. You demonstrated stored HTML injection with a harmless marker. A full finding would distinguish the write location, the reader location, the affected user role and any separately established execution behavior.',fix:'Store canonical data. Encode at each output sink; use a maintained sanitizer when rich HTML is required.',answer:M},
  {id:'stored-defense',module:'stored',title:'Protect every reader',minutes:6,kind:'choice',goal:'Public comments are encoded, but an admin review page uses raw HTML. Which fix covers the root cause?',lesson:'A stored value can reach multiple renderers. A safe public page does not protect an unsafe admin page. Storage itself is not the output context.',code:'publicPage.textContent = comment;\nadminPreview.innerHTML = comment;\nemailTemplate.renderRaw(comment);',context:'Multiple output sinks',source:'stored comment',sink:'three renderers',transform:'different per sink',choices:[['once','HTML-encode once before saving for every future use'],['sinks','Apply context-appropriate protection at each renderer'],['admin','Assume admins can safely view raw content']],answer:'sinks',hints:['The same value can be used in HTML, attributes or another format.','Protect the public, admin and email output separately.'],explanation:'Encode at the point of output for the actual context. Encoding once at storage couples the data to a context and can cause double encoding or mismatches. When rich HTML is a feature, apply a maintained HTML sanitizer and avoid unsafe mutations afterward.',fix:'Use safe sinks or context-aware templates in all reader views.'},
  {id:'source-sink',module:'dom',title:'Trace the source to the sink',minutes:8,kind:'trace',goal:'Identify the untrusted source and the HTML-parsing sink. The fragment is read by browser code; it is not sent as part of an HTTP request URL.',lesson:'A source provides untrusted data. A sink interprets or renders it. Follow every transformation between them. A dangerous sink name alone is not enough: the input must be controllable and the path reachable.',code:'const raw = location.hash.slice(1);\nconst name = decodeURIComponent(raw);\npreview.innerHTML = name;',context:'Client-side HTML flow',source:'location.hash',sink:'preview.innerHTML',transform:'percent decoding',fields:[{key:'source',label:'Untrusted source',options:['location.hash','decodeURIComponent','preview.innerHTML']},{key:'sink',label:'HTML-parsing sink',options:['location.hash','decodeURIComponent','preview.innerHTML']}],answer:{source:'location.hash',sink:'preview.innerHTML'},hints:['The source is read on the first line.','innerHTML asks the browser to parse a string as markup.'],explanation:'location.hash is the source; preview.innerHTML is the parsing sink. decodeURIComponent is a transform, not a safety boundary. The fragment can produce a DOM-based path without appearing in the server response.',fix:'Use preview.textContent = name when the feature only needs text.'},
  {id:'fragment-decode',module:'dom',title:'Follow one decoding step',minutes:9,kind:'dom',label:'Simulated URL fragment',placeholder:'#%3Cmark…',goal:'Supply a percent-encoded MRTD mark element, prefixed with #. The model decodes it once and passes it into the HTML sink. This never changes the actual site URL.',lesson:'Input encoding for transport is not output encoding. decodeURIComponent reverses percent encoding. A value that looked inert before decoding can become markup at the sink.',code:'const input = simulatedHash.slice(1);\nconst decoded = decodeURIComponent(input);\npreview.innerHTML = decoded; // modeled only',context:'Fragment → decode → HTML',source:'simulated fragment',sink:'innerHTML model',transform:'one percent decode',hints:['Encode the safe mark element with percent encoding.','Use #%3Cmark%20data-proof%3D%22MRTD%22%3EMRTD%3C%2Fmark%3E.'],explanation:'One percent-decoding step restored the HTML marker before the modeled sink. URL encoding was a transport representation, not a defense. Double-encoded input is not equivalent in this one-decode model.',fix:'Decode only as required, then use a text sink or a maintained rich-HTML sanitizer.',answer:'#'+encodeURIComponent(M)},
  {id:'safe-sink',module:'dom',title:'Repair the DOM sink',minutes:6,kind:'choice',goal:'The feature is a plain text greeting. Choose the repair that keeps angle brackets visible without parsing HTML.',lesson:'Safe DOM APIs can eliminate an entire parsing boundary. Keep the intended functionality in mind: plain text needs no HTML parser.',code:'const value = query.get("name");\ngreeting.innerHTML = value; // replace this',context:'Plain text DOM output',source:'URLSearchParams',sink:'greeting output',transform:'none',choices:[['text','greeting.textContent = value'],['encode','greeting.innerHTML = decodeURIComponent(value)'],['trust','greeting.innerHTML = value.trim()']],answer:'text',hints:['Choose the API that treats its value as text.','textContent does not parse HTML.'],explanation:'textContent treats the value as data. Trimming and decoding do not remove the HTML parsing boundary. Safe sink guidance depends on the API and purpose; a URL attribute still needs scheme validation.',fix:'greeting.textContent = value;'},
  {id:'encode-text',module:'encoding',title:'Encode for HTML text',minutes:8,kind:'encode',label:'Encoded output',placeholder:'&lt;…',goal:'Encode <MRTD & "ok"> for a template that writes an HTML text node. Use the lab encoder’s canonical form for all five special characters.',lesson:'Output encoding represents parser delimiters as data. The browser displays the original characters to the reader while preserving the surrounding HTML structure.',code:'Input:   <MRTD & "ok">\nContext: <p>${encodedValue}</p>\nMap: & → &amp;  < → &lt;  > → &gt;\n     " → &quot;  \' → &#39;',context:'HTML text',source:'raw display string',sink:'encoded HTML template',transform:'HTML entity encoding',hints:['Encode the original ampersand as &amp;.','The canonical answer is &lt;MRTD &amp; &quot;ok&quot;&gt;.'],explanation:'The delimiters are encoded and remain text at this sink. Encoding quotes is conservative in an HTML text node; it is essential when they delimit attributes. Do not run an encoder repeatedly over already-encoded output.',fix:'Use framework auto-escaping or a well-maintained context-aware encoder.',answer:'&lt;MRTD &amp; &quot;ok&quot;&gt;'},
  {id:'encode-attribute',module:'encoding',title:'Keep an attribute value intact',minutes:8,kind:'encode',label:'Encoded attribute value',placeholder:'Encode both double quotes…',goal:'Encode the two double quotes in the input " data-proof="MRTD so the whole string stays inside value="…". Use &quot; for each quote.',lesson:'Attribute encoding must cover the delimiter used by the surrounding markup. Keep attribute names fixed and values quoted. Encoding does not make an event-handler attribute a safe place for untrusted code.',code:'Input:   " data-proof="MRTD\nContext: <input value="${encodedValue}">',context:'Double-quoted attribute',source:'display string',sink:'value attribute',transform:'attribute encoding',hints:['Encode each double quote, including the first character.','Use &quot; data-proof=&quot;MRTD.'],explanation:'Both quote delimiters are encoded, so the string remains one value instead of adding a data-proof attribute. This applies to a normal text attribute such as value; avoid dynamic event handlers and validate URL schemes for href/src.',fix:'Prefer setting the value property directly.',answer:'&quot; data-proof=&quot;MRTD'},
  {id:'url-context',module:'encoding',title:'Validate before encoding a URL',minutes:8,kind:'choice',goal:'A profile link is user-controlled. What is the right sequence when the application permits only HTTPS links?',lesson:'HTML encoding preserves an HTML attribute boundary, but does not decide whether a URL scheme is allowed. URL validation and HTML attribute encoding solve different problems.',code:'<a href="${userLink}">Profile</a>\nAllowed scheme for this feature: https:',context:'URL inside an HTML attribute',source:'profile link',sink:'anchor.href',transform:'validation + encoding',choices:[['entities','Only HTML-encode angle brackets and quotes'],['allow','Parse the URL, require https:, then use a safe URL assignment or attribute encoder'],['prefix','Accept any string containing https somewhere']],answer:'allow',hints:['Check the parsed protocol, not a substring.','Validation decides where a link may go; encoding protects surrounding markup.'],explanation:'Use a standard URL parser and enforce the scheme and any destination policy. Then assign the validated URL through the DOM API or encode it for a quoted HTML attribute. Encoding a dangerous scheme does not make it an allowed destination.',fix:'Parse and validate URL.protocol === "https:"; apply any host allowlist the feature needs.'},
  {id:'filter-case',module:'filters',title:'Find a filter’s blind spot',minutes:9,kind:'filter',label:'Harmless HTML marker',placeholder:'Use a different tag-name case…',goal:'A toy filter removes lowercase mark elements only, before a case-insensitive HTML model. Use an uppercase MARK element and the MRTD proof attribute to show the mismatch.',lesson:'A blacklist compares strings; an HTML parser follows syntax rules. This intentionally tiny filter is not a sanitizer. The exercise studies parser mismatch with inert markup only.',code:'// Toy model: only removes lowercase tags\nclean = input.replace(/<mark\\b[^>]*>[\\s\\S]*?<\\/mark>/g, "");\n// HTML tag names are case-insensitive.',context:'Case-sensitive filter → HTML',source:'marker input',sink:'HTML model',transform:'lowercase-only removal',hints:['Keep the same inert element; change the tag-name case.','Use <MARK data-proof="MRTD">MRTD</MARK>.'],explanation:'The lowercase-only filter missed an uppercase tag that the HTML model recognizes. This establishes a filter inconsistency for the marker, not script execution. Real HTML sanitization must use a maintained parser-based library configured for the intended content.',fix:'Use textContent for text; use a maintained sanitizer with an explicit policy for rich HTML.',answer:'<MARK data-proof="MRTD">MRTD</MARK>'},
  {id:'sanitize',module:'filters',title:'Choose the right content policy',minutes:8,kind:'choice',goal:'A comment editor intentionally supports bold and italic formatting. Which strategy preserves formatting while controlling HTML?',lesson:'Encoding displays markup literally. Sanitization parses markup and removes content outside a policy. Neither should be replaced by a handcrafted list of forbidden words.',code:'Feature: allow <b> and <i> in comments\nReject active content and unsafe attributes\nRender the permitted formatting',context:'Intentional rich HTML',source:'rich comment',sink:'rich HTML output',transform:'sanitizer policy',choices:[['regex','Strip the word script with a regular expression'],['sanitizer','Use a maintained HTML sanitizer configured for the permitted tags and attributes'],['decode','HTML-encode, then decode before rendering']],answer:'sanitizer',hints:['The feature needs some markup, so plain text encoding changes its behavior.','Choose a maintained sanitizer, with a narrow policy and regular updates.'],explanation:'A maintained HTML sanitizer can preserve permitted formatting while removing disallowed structure and attributes. Keep it updated and do not concatenate untrusted content or perform unsafe mutations after sanitizing. The lab’s marker recognizer is a model, never a production sanitizer.',fix:'Apply a maintained sanitizer at the rich-HTML boundary; use text sinks elsewhere.'},
  {id:'csp-inline',module:'csp',title:'Predict an inline-script decision',minutes:9,kind:'choice',goal:'Predict what an enforced script-src \'self\' policy does to this inline proof script. The decision is modeled; the script is never inserted or executed.',lesson:'The self source permits matching same-origin script resources. By itself, it does not authorize inline script blocks. CSP adds a defense layer but does not fix unsafe output handling.',code:'Content-Security-Policy: script-src \'self\'\n\n<script>proof("MRTD")</script>\n// proof() is an inert lab-only notation.',context:'CSP · enforced',source:'inline proof notation',sink:'modeled script decision',transform:'script-src policy',choices:[['run','Allow because the HTML is same-origin'],['block','Block the inline script'],['repair','Rewrite the script into safe text']],answer:'block',hints:['self is not an inline-script permission.','There is no matching nonce or hash.'],explanation:'An enforced script-src with only self blocks this inline block. The browser does not rewrite unsafe HTML. Fix the sink as well as the policy, and inspect violations rather than assuming a missing visual effect means the injection was fixed.',fix:'Keep encoding/safe sinks. Deploy a deliberate CSP using nonces or hashes where appropriate.'},
  {id:'csp-nonce',module:'csp',title:'Understand a nonce boundary',minutes:10,kind:'choice',goal:'A script block has a matching nonce. A button has an inline onclick handler. Which is authorized by this policy? The nonce below is an illustrative placeholder.',lesson:'A valid script nonce authorizes that script element. It is not a general permission for inline event attributes. Production nonces must be unpredictable and generated for each response.',code:'script-src \'nonce-LAB_PLACEHOLDER\'\n\n<script nonce="LAB_PLACEHOLDER">proof("MRTD")</script>\n<button onclick="proof(\'MRTD\')">Test</button>',context:'CSP · nonce model',source:'two inline forms',sink:'script & event-handler decisions',transform:'nonce check',choices:[['both','Both the script block and the onclick attribute'],['script','The matching-nonce script block only'],['neither','Neither, because both are inline']],answer:'script',hints:['A nonce belongs to a script element.','The onclick attribute does not inherit the script element’s authorization.'],explanation:'The matching-nonce block is allowed by the modeled script policy. The inline event handler remains blocked without a separate applicable permission. Never reuse this placeholder as a real nonce, and never attach trusted nonces to untrusted script content.',fix:'Use fresh unpredictable per-response nonces; attach event listeners from trusted code.'},
  {id:'csp-report-only',module:'csp',title:'Separate reporting from enforcement',minutes:8,kind:'choice',goal:'An inline marker violates a report-only script policy. No enforced policy is present. Predict the policy’s effect.',lesson:'Report-only mode helps observe violations before enforcement. It does not block them. Another enforced policy can still block an action; this scenario explicitly has none.',code:'Content-Security-Policy-Report-Only: script-src \'none\'\nNo enforced CSP header\nInline proof notation: proof("MRTD")',context:'CSP · report-only',source:'inline proof notation',sink:'modeled CSP report',transform:'report without blocking',choices:[['block','Block execution because script-src is none'],['report','Report the violation without blocking it'],['silent','Silently fix the input encoding']],answer:'report',hints:['Read the complete header name.','Report-Only observes; it does not enforce.'],explanation:'The report-only policy records a violation but does not itself block the action. This exercise models the header behavior; the real lab always remains script-free in its preview. Report-only policies must be delivered as HTTP headers, not meta tags.',fix:'After evaluating reports, deploy an enforced policy while retaining safe rendering.'},
  {id:'debug-dom',module:'debug',title:'Compare the response with the DOM',minutes:10,kind:'choice',goal:'The HTTP response has no marker, but DevTools Elements shows it after client code runs. Where should you investigate next?',lesson:'View Source shows the response representation. Elements shows the current parsed and potentially mutated DOM. Compare both and use breakpoints to find who changed the node.',code:'HTTP response: <div id="preview"></div>\nClient: preview.innerHTML = decodeURIComponent(location.hash.slice(1));\nElements: <div id="preview"><mark …>MRTD</mark></div>',context:'Response vs live DOM',source:'fragment',sink:'client mutation',transform:'decode + DOM update',choices:[['server','Keep searching only in server response headers'],['dom','Trace the fragment and set a DOM mutation breakpoint on preview'],['report','Report confirmed script execution from the mark element alone']],answer:'dom',hints:['Which representation changes after page load?','Trace the browser code that mutates the target node.'],explanation:'Follow the client-side source and set a DOM subtree modification breakpoint to pause at the mutation. Inspect the call stack and transformed value. A mark element shows a markup change; it is not evidence that JavaScript executed.',fix:'Record the source, transforms, sink and observed result; repair the output boundary.'},
  {id:'capstone',module:'debug',title:'Build a precise evidence trail',minutes:12,kind:'capstone',goal:'Review this stored-to-DOM flow. Classify the delivery, identify the sink and select the fix for a plain text reader. Do not claim execution from an inert mark element.',lesson:'Advanced testing is precise reasoning, not louder payloads. Reproduce the write/read path, identify the exact boundary, separate observations from assumptions, and verify the fix with the same marker.',code:'// Writer\napi.saveComment(body);\n// Reader, later\nconst row = await api.latestComment();\nfeed.innerHTML = row.body;\n// Observed: a mark element appears; no scripts run.',context:'Stored delivery + DOM processing',source:'saved body',sink:'feed.innerHTML',transform:'API read',fields:[{key:'delivery',label:'Delivery pattern',options:['Reflected','Stored','Not controllable']},{key:'sink',label:'Parsing sink',options:['api.saveComment','feed.innerHTML','await']},{key:'fix',label:'Plain text repair',options:['feed.textContent = row.body','Remove the word script','Rely only on CSP']}],answer:{delivery:'Stored',sink:'feed.innerHTML',fix:'feed.textContent = row.body'},hints:['The comment is saved before the reader loads it.','The DOM sink is innerHTML; the plain text alternative is textContent.'],explanation:'This combines stored delivery with a DOM-based processing path. Your evidence proves stored HTML injection in the model. Record the submission and later read, the affected view, and the exact rendered marker. Execution and impact need separate evidence. Re-test after replacing innerHTML with textContent.',fix:'Use feed.textContent = row.body; keep the harmless regression marker.'},
];
export const marker = M;
